      hu: ["Nagy Konstantin császár 272-ben született a közeli Naissus városában.", "A mozaikok közül a legértékesebbek Medusa fejét és folyóisteneket ábrázolnak.", "A területet 1930-ban kezdték el szisztematikusan feltárni régészek.", "A villagazdaság öntözőrendszere a közeli Nišava folyóból kapta a vizet.", "A helyszínen több mint 80 bronzszobrot és egyéb műtárgyat találtak.", "A rezidencia falai mentén katonai barakkok maradványai is láthatóak."],
