    descriptionAdvanced: {
      de: "Die Festung Bač im Südwesten der Vojvodina ist das bedeutendste mittelalterliche Verteidigungsbauwerk in der Region und ein Paradebeispiel für eine Wasserburg. Sie wurde im 14. Jahrhundert unter der Herrschaft des ungarischen Königs Karl Robert von Anjou auf einer Insel im Fluss Mostonga errichtet. Die Anlage zeichnet sich durch einen unregelmäßigen fünfeckigen Grundriss mit massiven Backsteintürmen aus, wobei der zentrale Donjon der markanteste Teil ist. Im Laufe der Geschichte wechselte die Festung mehrfach den Besitzer zwischen Ungarn, Osmanen und Österreichern. Besonders prägend war die osmanische Besatzungszeit, in der die Burg umgebaut und eine Moschee integriert wurde. Nach der Zerstörung während des Rakoczi-Aufstands zu Beginn des 18. Jahrhunderts verlor die Festung ihre militärische Bedeutung und verfiel zusehends. Seit den 2000er Jahren finden umfangreiche Restaurierungsarbeiten statt, um die Anlage als kulturelles Erbe zu erhalten. Heute beherbergt der restaurierte Hauptturm ein Museum, das die wechselvolle Geschichte der Bačka dokumentiert. Die Festung ist für die Welterbeliste der UNESCO nominiert.",
      hu: "A bácsi vár a Vajdaság délnyugati részén található, a régió legjelentősebb középkori erődítménye, egyben a vízi várak típusának kiváló példája. Az erődöt a 14. században, I. Károly magyar király uralkodása alatt építették a Mostonga folyó egyik kanyarulatában kialakított szigeten. Az építmény szabálytalan ötszög alaprajzú, sarkaiban masszív bástyákkal, központjában pedig a jellegzetes, négyszintes lakótoronnyal (donjon). Történelme során többször gazdát cserélt a magyarok, az oszmánok és a Habsburgok között, stratégiai fekvése miatt kulcsfontosságú volt a Duna menti védelemben. Az oszmán uralom alatt (1529–1686) mecsetet és fürdőt is létesítettek a falakon belül. A II. Rákóczi Ferenc vezette szabadságharc során a vár súlyosan megrongálódott, katonai jelentőségét elvesztette, és romlásnak indult. A 2000-es években megkezdett nagyszabású restaurálási munkálatoknak köszönhetően a lakótorony ma múzeumként működik, és a helyszín az UNESCO világörökségi várományosi listáján szerepel.",
      ro: "Cetatea Bač, situată în sud-vestul Voivodinei, este cea mai importantă structură defensivă medievală din regiune, fiind un exemplu remarcabil de „cetate de apă”. A fost construită în secolul al XIV-lea sub domnia regelui Carol Robert de Anjou al Ungariei, pe o insulă formată de râul Mostonga. Complexul are un plan pentagonal neregulat, cu turnuri masive de cărămidă în colțuri și un turn central de tip donjon bine conservat. De-a lungul secolelor, cetatea a fost un punct strategic disputat între Regatul Ungariei, Imperiul Otoman și Imperiul Habsburgic. În timpul ocupației otomane, cetatea a fost adaptată nevoilor noi, inclusiv prin construcția unei moschei ale cărei urme sunt încă vizibile. Distrugerea cetății a avut loc la începutul secolului al XVIII-lea, în timpul răscoalei lui Rákóczi, după care fortificația a fost abandonată. Recent, cetatea a beneficiat de un amplu proiect de restaurare care a primit premiul Europa Nostra pentru conservarea patrimoniului cultural. Astăzi, turnul principal găzduiește o expoziție muzeală permanentă dedicată istoriei locale.",
      en: "The Bač Fortress, located in southwestern Vojvodina, is the most significant medieval defensive structure in the region and an outstanding example of a 'water fortress'. It was built in the 14th century during the reign of King Charles Robert of Anjou on an island within the Mostonga river. The fortress features an irregular pentagonal plan with massive brick towers, dominated by a well-preserved central keep, or donjon. Throughout its history, it served as a crucial strategic outpost contested between the Kingdom of Hungary, the Ottoman Empire, and the Habsburg Monarchy. During the Ottoman period (1529–1686), the site was enhanced with several buildings, including a mosque and a Turkish bath. The fortress suffered extensive damage during the Rákóczi Uprising in the early 18th century, leading to its eventual abandonment as a military stronghold. Systematic restoration efforts in recent decades have transformed the central tower into a museum, and the site is currently on the UNESCO Tentative List. It remains a prime destination for studying medieval architecture in the Pannonian Plain.",
      es: "La fortaleza de Bač es el monumento medieval más importante de Voivodina y fue construida en el siglo XIV bajo el rey húngaro Carlos Roberto.",
      pt: "A fortaleza de Bač é o monumento medieval mais importante da Voivodina e foi construída no século XIV sob o rei húngaro Carlos Roberto.",
      fr: "La forteresse de Bač est le monument médiéval le plus important de Voïvodine et a été construite au XIVe siècle sous le roi hongrois Charles Robert.",
    },
    factsAdvanced: {
      de: ["Die Festung wurde zwischen 1338 und 1342 unter König Karl Robert erbaut.", "Der zentrale Wohnturm hat eine Höhe von 18 Metern und fünf Stockwerke.", "Bač war Sitz eines der ältesten Erzbistümer in der ungarischen Geschichte.", "In der Festung befinden sich die Überreste eines türkischen Hamams aus dem 16. Jahrhundert.", "Die Restaurierung der Festung wurde 2018 mit dem Europa-Nostra-Preis ausgezeichnet.", "Die Festung war ursprünglich durch Kanäle direkt mit der Donau verbunden."],
      hu: ["A várat 1338 és 1342 között emelték vörös téglából és kőből.", "A központi lakótorony falvastagsága helyenként eléri a két métert.", "1526-ban a mohácsi csata után a várat I. Szulejmán szultán foglalta el.", "A várfalak között egy ferences rendi kolostor maradványai is megtalálhatóak.", "A Mostonga folyó kiszáradása miatt a vár eredeti vizesárka ma már száraz.", "A bácsi várrekonstrukció 2018-ban elnyerte az Europa Nostra-díjat."],
      ro: ["Cetatea a fost construită în perioada 1338-1342 din cărămidă arsă.", "Turnul central donjon are o bază pătrată și înălțimea de aproximativ 18 metri.", "Sit arheologic important, Bač a fost centrul unei arhiepiscopii catolice timpurii.", "În 1704, cetatea a fost incendiată și distrusă parțial de trupele imperiale.", "Proiectul 'Secolele orașului Bač' a revitalizat întregul centru istoric al localității.", "Cetatea face parte din traseul cultural internațional 'Ruta Dunării'."],
      en: ["Construction of the fortress took place between 1338 and 1342.", "The main donjon tower stands 18 meters high and features five levels.", "The site includes the ruins of a 16th-century Ottoman Turkish bath.", "Bač was once the seat of a Catholic Archbishopric, founded in the 11th century.", "The fortress was heavily damaged in 1704 during the Kuruc uprising.", "It received the prestigious Europa Nostra award for cultural heritage in 2018."],
      es: ["Construida entre 1338 y 1342", "Cuenta con un torreón de 18 metros de altura", "El complejo abarca 8 hectáreas de terreno", "Protegido como monumento cultural desde 1948", "Situada a 65 km de Novi Sad", "El estilo arquitectónico combina gótico y renacimiento"],
      pt: ["Construída entre 1338 e 1342", "Possui um torreão de 18 metros de altura", "O complexo abrange 8 hectares de terreno", "Protegido como monumento cultural desde 1948", "Localizada a 65 km de Novi Sad", "O estilo arquitetónico combina gótico e renascimento"],
      fr: ["Construite entre 1338 et 1342", "Dispose d'un donjon de 18 mètres de haut", "Le complexe couvre 8 hectares de terrain", "Protégé comme monument culturel depuis 1948", "Située à 65 km de Novi Sad", "Le style architectural combine gothique et renaissance"],
    },
