      hu: ["1381 és 1389 között épült fel", "Alapítói a Musić testvérek, Stefan és Lazar", "A morva építészeti iskola stílusát képviseli", "A freskók között látható a rigómezei csatában elhunyt alapítók arcképe", "Az Ibar folyó völgyében, Raška közelében található", "A 19. században jelentős helyreállítási munkákat végeztek rajta"],
