      es: "El monasterio de Staro Hopovo se encuentra enclavado en los bosques de Fruška Gora. Es conocido por su ubicación tranquila y sus orígenes medievales.",
      pt: "O Mosteiro de Staro Hopovo está situado nas florestas de Fruška Gora. É conhecido pela sua localização tranquila e origens medievais.",
