      hu: ["Középkori alapítás", "Fruška Gora", "Kolostoregyüttes", "Erdei környezet"],
      ro: ["Fundație medievală", "Fruška Gora", "Complex monastic", "Locație forestieră"],
      en: ["Medieval foundation", "Fruška Gora", "Monastery complex", "Forest location"],
      es: ["Fundación medieval", "Fruška Gora", "Complejo monástico", "Ubicación en el bosque"],
