      ro: ["Fondată în secolul al XV-lea de despotul Đorđe Branković", "Situată în Parcul Național Fruška Gora din Voivodina", "Biserica actuală din piatră a fost ridicată în 1752", "Este închinată Sfântului Pantelimon", "A fost distrusă aproape integral în al Doilea Război Mondial", "Face parte din grupul celor 16 mănăstiri din Fruška Gora"],
