      es: ["Fundado en el siglo XII", "Patrimonio de la Humanidad por la UNESCO", "Fundación de Stefan Nemanja", "Frescos medievales"],
      pt: ["Fundado no século XII", "Património Mundial da UNESCO", "Fundação de Stefan Nemanja", "Frescos medievais"],
      fr: ["Fondé au XIIe siècle", "Patrimoine mondial de l'UNESCO", "Fondation de Stefan Nemanja", "Fresques médiévales"],
