    type: "church",
    parent: "RS",
    name: { de: "Kloster Gračanica", hu: "Gračanica kolostor", ro: "Mănăstirea Gračanica", en: "Gračanica Monastery" },
    coords: [21.1911, 42.6025],
    description: {
      de: "Gračanica ist ein serbisch-orthodoxes Kloster aus dem 14. Jahrhundert. Es stellt einen Höhepunkt der byzantinisch-serbischen Architektur dar.",
      hu: "A Gračanica egy szerb ortodox kolostor a 14. századból. A bizánci-szerb építészet egyik csúcspontja.",
      ro: "Gračanica este o mănăstire ortodoxă sârbă din secolul al XIV-lea. Reprezintă un punct culminant al arhitecturii bizantino-sârbe.",
      en: "Gračanica is a Serbian Orthodox monastery dating back to the 14th century. It represents a pinnacle of Byzantine-Serbian architecture.",
      es: "Gračanica es un monasterio ortodoxo serbio del siglo XIV. Representa un punto culminante de la arquitectura bizantino-serbia.",
      pt: "Gračanica é um mosteiro ortodoxo sérvio do século XIV. Representa um ponto alto da arquitetura bizantino-sérvia.",
      fr: "Gračanica est un monastère orthodoxe serbe du XIVe siècle. Il représente un sommet de l'architecture byzantino-serbe.",
    },
    facts: {
      de: ["Erbaut 14. Jahrhundert", "UNESCO-Weltkulturerbe", "Byzantinisch-serbischer Stil", "Historische Fresken"],
      hu: ["14. században épült", "UNESCO világörökség", "Bizánci-szerb stílus", "Történelmi freskók"],
      ro: ["Construită în sec. XIV", "Patrimoniu UNESCO", "Stil bizantino-sârb", "Fresce istorice"],
      en: ["Built 14th century", "UNESCO World Heritage site", "Byzantine-Serbian style", "Historical frescoes"],
      es: ["Construido en el siglo XIV", "Patrimonio de la Humanidad por la UNESCO", "Estilo bizantino-serbio", "Frescos históricos"],
      pt: ["Construído no século XIV", "Património Mundial da UNESCO", "Estilo bizantino-sérvio", "Frescos históricos"],
      fr: ["Construit au XIVe siècle", "Patrimoine mondial de l'UNESCO", "Style byzantino-serbe", "Fresques historiques"],
    },
    imageHint: "Gračanica Monastery architecture",
    descriptionAdvanced: {
      de: "Das Kloster Gračanica wurde im Jahr 1321 von König Stefan Milutin auf den Ruinen einer Basilika aus dem 6. Jahrhundert errichtet. Es stellt den Höhepunkt der serbisch-byzantinischen Architektur dar und ist für seine harmonischen Proportionen und die komplexe Struktur aus fünf Kuppeln bekannt. Das Gebäude ist in Form eines doppelt eingeschriebenen Kreuzes konzipiert, wobei die Fassade durch den meisterhaften Einsatz von Ziegeln und Steinen lebendige Muster erzeugt. Im Inneren befinden sich einige der am besten erhaltenen Fresken des 14. Jahrhunderts, die sowohl religiöse Szenen als auch Porträts der Nemanjić-Dynastie in prachtvollen Gewändern zeigen. Besonders berühmt ist die Darstellung der 'Himmelsleiter'. Seit 2006 gehört Gračanica als Teil der Stätte 'Mittelalterliche Denkmäler im Kosovo' zum UNESCO-Welterbe. Trotz Kriegen und Belagerungen blieb die Kirche fast vollständig in ihrer ursprünglichen Form erhalten. Das Kloster ist bis heute ein bedeutendes religiöses und kulturelles Zentrum für die serbische Gemeinschaft in der Region.",
      hu: "A Gračanica-kolostort 1321-ben alapította Stefan Milutin király egy 6. századi bazilika romjain. Az épület a szerb-bizánci építészet csúcspontját képviseli, harmonikus arányairól és az ötkupolás szerkezet bonyolult eleganciájáról ismert. A templom kettős kereszt alaprajzú, homlokzatát a téglák és kövek mesteri váltakozása díszíti, ami vibráló mintázatot hoz létre. A belső térben a 14. századi freskófestészet legszebb példái láthatók, vallási jelenetekkel és a Nemanjić-dinasztia uralkodóinak pompás viseletben ábrázolt portréival. Különösen híres a 'Mennyei lajtorja' ábrázolása. 2006 óta Gračanica az UNESCO Világörökség része a 'Koszovó középkori műemlékei' csoport tagjaként. A háborúk és ostromok ellenére a templom szinte teljes egészében megőrizte eredeti formáját. A kolostor mindmáig fontos vallási és kulturális központ a régió szerb közössége számára, az identitás és a hit megőrzésének bástyája.",
      ro: "Mănăstirea Gračanica a fost ctitorită în anul 1321 de regele Stefan Milutin pe ruinele unei basilici din secolul al VI-lea. Reprezintă apogeul arhitecturii sârbo-bizantine, fiind renumită pentru proporțiile sale armonioase și structura complexă cu cinci cupole. Clădirea are un plan de cruce înscrisă dublă, iar fațada este decorată prin utilizarea măiestrită a cărămizii și pietrei, creând modele vibrante. În interior se află unele dintre cele mai bine conservate fresce din secolul al XIV-lea, ilustrând scene religioase și portrete ale dinastiei Nemanjić în haine ceremoniale. Foarte celebră este reprezentarea 'Scării Raiului'. Din anul 2006, Gračanica face parte din Patrimoniul Mondial UNESCO, fiind inclusă în situl 'Monumentele medievale din Kosovo'. În ciuda războaielor și asediilor, biserica și-a păstrat aproape integral forma originală. Mănăstirea rămâne până astăzi un centru religios și cultural vital pentru comunitatea sârbă din regiune.",
      en: "Gračanica Monastery was founded in 1321 by King Stefan Milutin on the ruins of a 6th-century basilica. It represents the pinnacle of Serbian-Byzantine architecture, renowned for its harmonious proportions and intricate five-domed structure. The church is designed as a double-inscribed cross, and its facade features masterful brick-and-stone patterns that create a vibrant aesthetic. Inside are some of the best-preserved frescoes of the 14th century, depicting religious scenes and portraits of the Nemanjić dynasty in lavish ceremonial dress. The depiction of the 'Heavenly Ladder' is particularly famous. Since 2006, Gračanica has been a UNESCO World Heritage site as part of the 'Medieval Monuments in Kosovo' group. Despite centuries of conflict, the church has survived almost entirely in its original form. The monastery continues to serve as a vital religious and cultural hub for the local Serbian community, symbolizing endurance and faith.",
      es: "El monasterio de Gračanica se encuentra en Kosovo, cerca de la ciudad de Priština. Fue construido en el siglo XIV por el rey Stefan Milutin y está dedicado a la Dormición de la Madre de Dios. El monasterio es una obra maestra de la arquitectura serbio-bizantina con una cúpula central y cinco cúpulas más. Los frescos del siglo XIV están excepcionalmente bien conservados y muestran escenas bíblicas. Gračanica es parte del Patrimonio Mundial de la UNESCO 'Monumentos medievales en Kosovo'. El monasterio es un convento de monjas activo.",
      pt: "O mosteiro de Gračanica encontra-se no Kosovo, perto da cidade de Priština. Foi construído no século XIV pelo rei Stefan Milutin e está dedicado à Dormição da Mãe de Deus. O mosteiro é uma obra-prima da arquitetura sérvio-bizantina com uma cúpula central e cinco cúpulas mais. Os frescos do século XIV estão excecionalmente bem preservados e mostram cenas bíblicas. Gračanica é parte do Património Mundial da UNESCO 'Monumentos medievais no Kosovo'. O mosteiro é um convento de monjas ativo.",
      fr: "Le monastère de Gračanica est situé au Kosovo, près de la ville de Pristina. Il a été construit au XIVe siècle par le roi Stefan Milutin et est dédié à la Dormition de la Mère de Dieu. Le monastère est un chef-d'œuvre de l'architecture serbo-byzantine avec un dôme central et cinq autres dômes. Les fresques du XIVe siècle sont exceptionnellement bien conservées et montrent des scènes bibliques. Gračanica fait partie du site du patrimoine mondial de l'UNESCO 'Monuments médiévaux au Kosovo'. Le monastère est un couvent de religieuses actif.",
    },
