      en: ["Completed in 1321 by King Stefan Milutin", "A masterpiece of Late Byzantine and Serbian architecture", "Features a distinctive and complex five-dome layout", "Listed as a UNESCO World Heritage site since 2006", "Contains remarkably preserved 14th-century frescoes", "Built on the foundations of a 6th-century Christian basilica"],
      es: ["El monasterio fue construido en el siglo XIV por el rey Stefan Milutin.", "Está dedicado a la Dormición de la Madre de Dios.", "La arquitectura tiene una cúpula central y cinco más.", "Los frescos datan del siglo XIV.", "Es Patrimonio de la Humanidad por la UNESCO desde 2004.", "El monasterio está cerca de Priština."],
      pt: ["O mosteiro foi construído no século XIV pelo rei Stefan Milutin.", "É dedicado à Dormição da Mãe de Deus.", "A arquitetura tem uma cúpula central e cinco mais.", "Os frescos datam do século XIV.", "É Património Mundial da UNESCO desde 2004.", "O mosteiro está perto de Priština."],
      fr: ["Le monastère a été construit au XIVe siècle par le roi Stefan Milutin.", "Il est dédié à la Dormition de la Mère de Dieu.", "L'architecture a un dôme central et cinq autres.", "Les fresques datent du XIVe siècle.", "Il est inscrit au patrimoine mondial de l'UNESCO depuis 2004.", "Le monastère est situé près de Pristina."],
