      es: ["Construido en el estilo de la escuela de Raška", "Fundación del poderoso rey Stefan Milutin", "Alguna vez fue uno de los monasterios más ricos de Serbia", "Situado cerca de Zvečan en Kosovo", "La iglesia está dedicada a San Esteban", "Fue dañado por los turcos en el siglo XV"],
