      en: ["Founded around 1270 by Queen Helen of Anjou", "Displays a rare blend of Byzantine and Gothic styles", "Located in the Brvenica valley near the Golija Mountains", "The main church is dedicated to the Annunciation", "Underwent major restoration in the 20th century", "Currently functions as an active nunnery"],
