      pt: ["Mencionado em biografias antigas de São Sava", "Pertencia ao núcleo do estado sérvio", "Escavações históricas iniciadas no séc. XX", "Localizado no sudoeste montanhoso da Sérvia", "Ligação com o reinado de Stefan Nemanja", "Importante para o estudo da história de Raška"],
