    imageHint: "Studenica Monastery architecture",
    descriptionAdvanced: {
      de: "Das Kloster Studenica, gegründet im Jahr 1186 von Stefan Nemanja, gilt als das wichtigste Kloster Serbiens und wird oft als 'Mutter aller serbischen Klöster' bezeichnet. Die Anlage liegt in einer malerischen Berglandschaft bei Kraljevo und ist von einer kreisförmigen Mauer mit markanten Türmen umgeben. Die Hauptkirche der Gottesmutter ist ein Meisterwerk der Raška-Schule, erbaut aus poliertem weißem Marmor, was ihr ein strahlendes und zeitloses Aussehen verleiht. Die romanische Außendekoration der Fenster und Portale steht im Kontrast zu den prächtigen byzantinischen Fresken im Inneren, darunter die berühmte Kreuzigung Christi aus dem Jahr 1209. Studenica beherbergt die Reliquien des Heiligen Nemanja (Symeon), des Heiligen Sava und des Heiligen Simon. Seit 1986 gehört das Kloster zum UNESCO-Welterbe. Es ist nicht nur ein Ort der Anbetung, sondern auch ein Symbol für die Entstehung des serbischen Staates und der nationalen Identität im Mittelalter.",
      hu: "A Studenica-kolostort 1186-ban alapította Stefan Nemanja, és Szerbia legfontosabb egyházi központjaként tartják számon, gyakran a 'szerb kolostorok anyjaként' emlegetve. A Kraljevo közelében, festői hegyi környezetben fekvő épületegyüttest bástyákkal megerősített kör alakú fal veszi körül. A főtemplom, az Istenanya-templom a Raška-stílus mesterműve, fehér márványból épült, ami ragyogó és időtlen megjelenést kölcsönöz neki. A homlokzat román stílusú kőfaragásai éles ellentétben állnak a belső tér pompás bizánci freskóival, amelyek közül a leghíresebb az 1209-ben festett Keresztrefeszítés. Studenica őrzi Szent Simeon (Nemanja), Szent Száva és Szent Simon ereklyéit, így a legfontosabb nemzeti zarándokhely. 1986 óta az UNESCO Világörökség része. Nem csupán vallási központ, hanem a szerb államiság és a középkori nemzeti identitás megszületésének szimbóluma is.",
      ro: "Mănăstirea Studenica, fondată în anul 1186 de Stefan Nemanja, este considerată cea mai importantă mănăstire din Serbia, fiind supranumită 'Mama tuturor mănăstirilor sârbești'. Complexul este situat într-un cadru montan pitoresc lângă Kraljevo și este înconjurat de ziduri circulare cu turnuri de apărare. Biserica principală a Maicii Domnului este o capodoperă a școlii de la Raška, construită din marmură albă șlefuită, ceea ce îi conferă un aspect radiant și atemporal. Decorațiunile exterioare romanice ale ferestrelor și portalurilor contrastează cu frescele bizantine superbe din interior, printre care se numără faimoasa Răstignire din 1209. Studenica adăpostește moaștele Sfântului Simeon (Nemanja), ale Sfântului Sava și ale Sfântului Simon. Din anul 1986, mănăstirea face parte din Patrimoniul Mondial UNESCO. Ea reprezintă nu doar un lăcaș de cult, ci și un simbol al nașterii statului sârb și al identității naționale din perioada medievală.",
      en: "Studenica Monastery, founded in 1186 by Stefan Nemanja, is regarded as the most important monastery in Serbia and is often called the 'Mother of all Serbian Monasteries.' Located in a picturesque mountain setting near Kraljevo, the complex is enclosed by circular walls with defensive towers. The main Church of the Virgin is a masterpiece of the Raška school, constructed from polished white marble, giving it a brilliant and timeless appearance. Its Romanesque exterior carvings on windows and portals contrast with the magnificent Byzantine frescoes inside, including the world-famous Crucifixion painted in 1209. Studenica houses the relics of Saint Simeon (Nemanja), Saint Sava, and Saint Simon, making it a major site of veneration. Since 1986, the monastery has been a UNESCO World Heritage site. It serves not only as a place of worship but as a profound symbol of the foundation of the Serbian state and medieval national identity.",
      es: "El monasterio de Studenica fue fundado a finales del siglo XII por Stefan Nemanja, el fundador de la dinastía Nemanjić, y sirvió como centro espiritual de la Serbia medieval. La Iglesia de la Virgen, una obra maestra de la arquitectura románico-bizantina, fue construida entre 1183 y 1196 en mármol blanco. Los frescos del siglo XIII, incluida la famosa escena de la crucifixión, son ejemplos destacados del arte bizantino. El monasterio fue incluido en la lista del Patrimonio Mundial de la UNESCO en 1986 y alberga una comunidad monástica activa. Desempeñó un papel central en el desarrollo de la cultura y la literatura medieval serbia.",
      pt: "O mosteiro de Studenica foi fundado no final do século XII por Stefan Nemanja, fundador da dinastia Nemanjić, e serviu como centro espiritual da Sérvia medieval. A Igreja da Virgem, uma obra-prima da arquitetura românico-bizantina, foi construída entre 1183 e 1196 em mármore branco. Os frescos do século XIII, incluindo a famosa cena da crucificação, são exemplos destacados da arte bizantina. O mosteiro foi incluído na lista do Património Mundial da UNESCO em 1986 e alberga uma comunidade monástica ativa. Desempenhou um papel central no desenvolvimento da cultura e literatura sérvia medieval.",
      fr: "Le monastère de Studenica a été fondé à la fin du XIIe siècle par Stefan Nemanja, fondateur de la dynastie Nemanjić, et a servi de centre spirituel à la Serbie médiévale. L'église de la Vierge, chef-d'œuvre de l'architecture romano-byzantine, a été construite entre 1183 et 1196 en marbre blanc. Les fresques du XIIIe siècle, dont la célèbre scène de la crucifixion, sont des exemples remarquables de l'art byzantin. Le monastère a été inscrit sur la liste du patrimoine mondial de l'UNESCO en 1986 et abrite une communauté monastique active. Il a joué un rôle central dans le développement de la culture et de la littérature serbes médiévales.",
    },
