      hu: ["1186-ban alapította Stefan Nemanja fejedelem", "1986 óta az UNESCO Világörökség része", "A főtemplom falai fehér márványból készültek", "Itt található az 1209-es híres Keresztrefeszítés-freskó", "Szent Simeon és Szent Száva ereklyéinek őrzőhelye", "A szerb történelem legjelentősebb kolostoraként ismert"],
      ro: ["Fondată în anul 1186 de către Stefan Nemanja", "Inclusă în Patrimoniul UNESCO din anul 1986", "Biserica principală este zidită din marmură albă", "Păstrează faimoasa frescă a Răstignirii din anul 1209", "Adăpostește moaștele Sfinților Simeon și Sava", "Este considerată cea mai importantă mănăstire sârbească"],
      en: ["Founded in 1186 by Grand Prince Stefan Nemanja", "UNESCO World Heritage site since 1986", "The main church is built from polished white marble", "Home to the iconic 1209 Crucifixion fresco", "Houses the relics of Saint Simeon and Saint Sava", "Regarded as the most important monastery in Serbian history"],
