    imageHint: "Beočin Monastery Fruška Gora",
    descriptionAdvanced: {
      de: "Das Kloster Beočin liegt am Nordhang des Fruška-Gora-Gebirges am Rande der gleichnamigen Stadt Beočin. Es wurde erstmals in osmanischen Dokumenten des Jahres 1566 erwähnt, wobei die ursprüngliche Gründung vermutlich älter ist und der Überlieferung nach auf das 15. Jahrhundert zurückgeht. Die heutige Klosterkirche, die der Himmelfahrt Christi geweiht ist, wurde im 18. Jahrhundert im barocken Stil mit deutlichen Einflüssen der traditionellen serbischen Architektur neu errichtet. Das Kloster ist berühmt für seine wunderschöne Parkanlage, die im 19. Jahrhundert angelegt wurde und seltene Pflanzenarten beherbergt, die von Mönchen aus fernen Regionen mitgebracht wurden. Im Inneren der Kirche befindet sich eine prächtige Ikonostase, die von Janko Halkozović und Teodor Kračun gestaltet wurde, zwei der bedeutendsten serbischen Maler des Barock. Das Kloster erlitt während der Weltkriege Schäden, wurde jedoch umfassend restauriert und dient heute als Nonnenkloster. Eine besondere religiöse Bedeutung hat Beočin durch die Verehrung der wundertätigen Ikone der Gottesmutter von Beočin, die viele Pilger anzieht, die um Heilung und Beistand bitten. Die Ruhe der Anlage und die architektonische Eleganz machen es zu einem der am häufigsten besuchten Klöster in der Nähe von Novi Sad.",
      hu: "A Beočin-kolostor a Fruška Gora hegység északi lejtőjén található, az azonos nevű település szélén. Az első írásos emlékek róla egy 1566-os oszmán dokumentumból származnak, de a hagyomány szerint alapítása ennél jóval korábbi, vélhetően a 15. századra nyúlik vissza. A mai templomot, amelyet Krisztus mennybemenetelének szenteltek, a 18. század közepén építették újjá barokk stílusban, ötvözve azt a hagyományos szerb építészeti elemekkel. A kolostor egyik legfőbb vonzereje a gyönyörű park, amelyet a 19. században alakítottak ki, és ahol számos ritka növényfaj található, melyeket egykor a szerzetesek hoztak távoli vidékekről. A templomban látható monumentális ikonosztáz Janko Halkozović és Teodor Kračun munkája, akik a szerb barokk festészet legkiválóbb mesterei voltak. A kolostor a világháborúk alatt károkat szenvedett, de a későbbi felújítások visszaadták eredeti fényét. Jelenleg aktív női kolostorként működik, és a hívők körében különösen híres a 'Beočini Istenanya' csodatévő ikonjáról. A hely békéje és az épületek eleganciája miatt az Újvidék környéki kirándulók és zarándokok egyik kedvelt célpontja.",
      ro: "Mănăstirea Beočin este situată pe versantul nordic al muntelui Fruška Gora, la marginea orașului cu același nume. Prima atestare documentară apare în registrele otomane din 1566, deși se crede că mănăstirea a fost întemeiată mult mai devreme, posibil în secolul al XV-lea. Actuala biserică, închinată Înălțării Domnului, a fost reconstruită în secolul al XVIII-lea, fiind un exemplu remarcabil de arhitectură barocă cu accente tradiționale sârbești. Mănăstirea este faimoasă pentru parcul său dendrologic superb, amenajat în secolul al XIX-lea, care adăpostește specii de plante rare aduse de călugări din diverse colțuri ale lumii. Interiorul bisericii este decorat cu o iconostasă spectaculoasă, realizată de Janko Halkozović și Teodor Kračun, doi dintre cei mai mari pictori sârbi ai barocului. Deși a suferit degradări în timpul războaielor mondiale, mănăstirea a fost restaurată integral și funcționează astăzi ca mănăstire de maici. Un loc special în inima credincioșilor îl ocupă icoana făcătoare de minuni a Maicii Domnului de la Beočin, care atrage numeroși pelerini. Atmosfera de liniște și frumusețea peisajului fac din Beočin una dintre cele mai vizitate mănăstiri din apropierea orașului Novi Sad.",
      en: "Beočin Monastery is situated on the northern slopes of Mount Fruška Gora, on the outskirts of the town of Beočin. It was first mentioned in Ottoman records in 1566, though historical tradition suggests it was founded earlier, possibly in the 15th century. The current church, dedicated to the Ascension of Christ, was rebuilt in the 18th century in a Baroque style that incorporates traditional Serbian architectural features. The monastery is renowned for its magnificent park and botanical garden, established in the 19th century, which features rare plant species brought back by monks from their travels. Inside the church, visitors can admire a splendid iconostasis created by Janko Halkozović and Teodor Kračun, two of the most prominent Serbian Baroque painters. Although the monastery was damaged during the world wars, it has since been fully restored and now serves as an active nunnery. Beočin holds significant religious importance due to the miracle-working icon of the Mother of God of Beočin, which attracts pilgrims seeking spiritual healing and guidance. The combination of its serene environment and architectural elegance makes it one of the most popular monastic destinations near Novi Sad.",
      es: "El monasterio de Beočin se menciona por primera vez en documentos otomanos en 1566 y hoy es conocido por su magnífico parque y la iglesia convertida al estilo barroco.",
      pt: "O mosteiro de Beočin é mencionado pela primeira vez em documentos otomanos em 1566 e hoje é conhecido pelo seu magnífico parque e a igreja convertida ao estilo barroco.",
      fr: "Le monastère de Beočin est mentionné pour la première fois dans des documents ottomans en 1566 et est aujourd'hui connu pour son magnifique parc et son église convertie au style baroque.",
    },
