      hu: ["Az első írásos említés a kolostorról 1566-ból származik.", "A mai barokk templom 1732 és 1740 között épült fel.", "Az ikonosztáz Teodor Kračun, a híres szerb barokk festő egyik fő műve.", "A kolostor parkját a 19. században francia mintára alakították ki.", "Itt őrzik a 'Beočini Istenanya' csodatévő ikont, amely a hívők szerint gyógyító erejű.", "A kolostor kertjében egy több mint 150 éves platánfa is található."],
      ro: ["Mănăstirea a fost documentată pentru prima dată de turci în 1566.", "Biserica actuală a fost ridicată în stil baroc între anii 1732 și 1740.", "Iconostasul bisericii a fost pictat în 1765 de maeștrii Halkozović și Kračun.", "Grădina mănăstirii conține specii rare de conifere aduse din Orient.", "Moaștele Sfântului Arsenie Sremac au fost păstrate aici între 1815 și 1839.", "Mănăstirea servește în prezent drept lăcaș de cult pentru o comunitate de maici."],
      en: ["The first official record of the monastery dates back to 1566.", "The present-day church was constructed in the Baroque style between 1732 and 1740.", "The iconic iconostasis was completed in 1765 by Halkozović and Kračun.", "Its park was professionally landscaped in the 19th century and contains over 200 species.", "The monastery was home to the relics of Saint Arsenije of Srem in the early 19th century.", "It is famous for the 'Mother of God' icon, believed to have performed miracles since 1740."],
      es: ["El edificio actual data de 1732", "Posee una valiosa biblioteca y tesorería", "Sirvió como residencia para obispos serbios", "Famoso por el icono milagroso de la Madre de Dios", "No fue destruido en la Segunda Guerra Mundial", "El parque del monasterio contiene especies de árboles raras"],
