      en: ["The monastery was founded in the early 16th century by Jelena Štiljanović.", "The interior frescoes were completed in 1588.", "It is dedicated to Saint Petka (Saint Paraskeva).", "The monastery's iconostasis was replaced in 1735.", "Significant damage occurred during World War II during the regional occupation.", "It is one of the sixteen historic monasteries of Fruška Gora."],
