      pt: ["Dedicado a São Nicolau", "Mencionado pela primeira vez em fontes otomanas de 1566", "Foi renovado fundamentalmente em estilo barroco em 1744", "Quase totalmente destruído na Segunda Guerra Mundial", "A reconstrução durou até ao ano 2000", "Possui um iconostase do século XVIII"],
