      en: ["Tradition dates the foundation to the 12th century by a founder named Priva.", "The earliest written evidence of the monastery is from 1566.", "Construction of the current church lasted from 1742 to 1760.", "The site is dedicated to the Holy Archangels Michael and Gabriel.", "It holds the westernmost position among the Fruška Gora monasteries.", "The interior iconostasis was decorated by Kuzman Kolarić in 1786."],
