    imageHint: "Končul Monastery near Raška",
    descriptionAdvanced: {
      de: "Das Kloster Končul, auch bekannt als Nikoljača, liegt am linken Ufer des Flusses Ibar in der Nähe der Stadt Raška im Südwesten Serbiens. Es wurde im Jahr 1175 vom großen Župan Stefan Nemanja gegründet und ist dem Heiligen Nikolaus geweiht. Die Kirche gehört architektonisch zur Raška-Schule und zeichnet sich durch ihre harmonischen Proportionen und die Verwendung von massivem Stein aus. In der mittelalterlichen Geschichte Serbiens war Končul ein bedeutendes kulturelles Zentrum und der Sitz des Bistums Raška. Während der Jahrhunderte der osmanischen Besatzung verfiel das Kloster und lag lange Zeit in Trümmern, bis es im 19. Jahrhundert teilweise wieder aufgebaut wurde. Umfangreiche archäologische Ausgrabungen und Restaurierungen in der Moderne haben die ursprüngliche Pracht des Grundrisses und wertvolle Freskenreste ans Licht gebracht. Heute ist das Kloster ein aktives geistliches Zentrum und ein geschütztes Kulturdenkmal, das die Anfänge des serbischen Staates repräsentiert.",
      hu: "A Končul-kolostor, más néven Nikoljača, az Ibar-folyó bal partján található, Raška városa mellett, Délnyugat-Szerbiában. A kolostort 1175-ben alapította Stefan Nemanja nagyzsupán, a templomot pedig Szent Miklós tiszteletére szentelték fel. Építészeti szempontból a rasi iskola egyik jeles képviselője, amely a bizánci térszervezést ötvözi a román stílusú kőfaragással. A középkorban a rasi püspökség székhelyeként fontos politikai és vallási szerepet játszott a formálódó szerb államban. A török hódoltság idején a kolostor súlyosan megrongálódott és elhagyatottá vált, újjáépítése csak a 19. században kezdődött meg. A modern kori régészeti feltárások során értékes 14. századi freskótöredékek és középkori sírok kerültek elő a területén. Napjainkban a kolostor ismét aktív hitéletet él, és a Nemanjić-dinasztia korai korszakának egyik legfontosabb történelmi emlékhelye.",
      ro: "Mănăstirea Končul, cunoscută și sub numele de Nikoljača, este situată pe malul stâng al râului Ibar, în apropierea orașului Raška din sud-vestul Serbiei. A fost ctitorită în anul 1175 de către marele jupan Ștefan Nemanja, fiind dedicată Sfântului Nicolae. Arhitectura bisericii aparține școlii de la Raška, caracterizată prin îmbinarea planului bizantin cu elemente decorative exterioare de factură romanică. În perioada medievală, Končul a fost un centru cultural de prim rang și reședința episcopiei de Raška, jucând un rol crucial în consolidarea bisericii sârbe. Mănăstirea a suferit distrugeri majore în timpul incursiunilor otomane, rămânând în stare de ruină pentru perioade lungi până la restaurările din secolul al XIX-lea. Cercetările arheologice recente au scos la iveală fragmente valoroase de frescă și morminte ale unor personalități istorice importante. Astăzi, mănăstirea este un monument cultural protejat și un loc de pelerinaj activ, păstrând memoria originilor statului sârb medieval.",
      en: "Končul Monastery, also known as Nikoljača, is situated on the left bank of the Ibar River near the town of Raška in southwestern Serbia. It was founded in 1175 by Grand Župan Stefan Nemanja and is dedicated to Saint Nicholas. The church architecture is a prime example of the Raška school, blending Byzantine internal space with Romanesque exterior stone masonry. During the Middle Ages, Končul was a major cultural center and the official seat of the Bishopric of Raška, making it central to the religious life of the Nemanjić state. The monastery fell into decay during the Ottoman period and remained largely in ruins until restoration efforts began in the 19th century. Modern archaeological excavations have revealed significant 14th-century fresco fragments and medieval burials within the complex. Currently, the monastery is an active religious site and is legally protected as a cultural monument of exceptional importance, reflecting the early centuries of Serbian sovereignty.",
      es: "El monasterio Končul, situado a orillas del río Ibar, fue fundado en el siglo XI y fue un importante centro religioso del primer estado serbio.",
      pt: "O Mosteiro de Končul, situado nas margens do rio Ibar, foi fundado no século XI e foi um importante centro religioso do primeiro estado sérvio.",
      fr: "Le monastère de Končul, situé sur les rives de l'Ibar, a été fondé au XIe siècle et fut un centre religieux important du premier État serbe.",
    },
