      hu: ["A kolostort 1175-ben alapította Stefan Nemanja nagyzsupán.", "Szent Miklós tiszteletére szentelték, ezért Nikoljača néven is ismert.", "A középkorban itt volt a rasi ortodox püspökség székhelye.", "Az épület a rasi építészeti iskola korai stílusjegyeit hordozza.", "A törökök pusztítása után az épület évszázadokig romokban állt.", "A kolostor az Ibar-folyó bal partján fekszik, Raška városának közelében."],
      ro: ["Mănăstirea a fost fondată în anul 1175 de Ștefan Nemanja.", "Este cunoscută și sub numele de Nikoljača, fiind dedicată Sfântului Nicolae.", "A servit drept sediu al episcopiei de Raška în secolele XII-XIV.", "Biserica reprezintă un monument tipic al școlii de arhitectură de la Raška.", "Mănăstirea a fost complet abandonată timp de aproape două secole sub otomani.", "Locația sa este pe malul râului Ibar, la ieșirea din orașul Raška."],
